-- UZH Institut für Informatik public company facts retrieved on 2026-10-20.
-- Imported entries are initiative-list entries, not partner firms.
CREATE TEMPORARY TABLE uzh_initiative_import (
  id CHAR(36) NOT NULL PRIMARY KEY, name VARCHAR(200) NOT NULL, location VARCHAR(160) NOT NULL,
  email VARCHAR(254) NULL, contact_person VARCHAR(200) NULL, phone VARCHAR(40) NULL,
  description TEXT NOT NULL, website VARCHAR(2048) NULL, internship_url VARCHAR(2048) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


SELECT source.id, source.name, source.location, JSON_ARRAY('Informatik-Praktikum'), source.email, source.contact_person, source.phone, source.description, source.website, FALSE, TRUE, source.internship_url, NULL
FROM uzh_initiative_import source
WHERE NOT EXISTS (SELECT 1 FROM companies existing WHERE LOWER(existing.name) = LOWER(source.name));

UPDATE companies existing JOIN uzh_initiative_import source ON LOWER(existing.name) = LOWER(source.name)
SET existing.initiative_listed = TRUE,
    existing.contact_person = COALESCE(existing.contact_person, source.contact_person),
    existing.email = COALESCE(existing.email, source.email),
    existing.phone = COALESCE(existing.phone, source.phone),
    existing.website = COALESCE(existing.website, source.website),
    existing.internship_url = COALESCE(existing.internship_url, source.internship_url),
    existing.description = COALESCE(existing.description, source.description);

DROP TEMPORARY TABLE uzh_initiative_import;
